r = pd.read_csv('data/ratings.csv.gz', dtype={'rating_id': str}, parse_dates=['rated_at'])
r = r.sort_values('rating_id').reset_index(drop=True)
s = pd.read_csv('reference/feature_sample.csv')
j = s.merge(r[['rating_id','member_id','rated_at','liked']], on='rating_id')

def variants(mid, t):
    m = r[(r.member_id==mid) & (r.rated_at < t)]
    out={}
    for N in [10,20,30,50]:
        out['raw%d'%N] = m.tail(N).liked.mean() if len(m) else np.nan
        for keep in ['first','last']:
            d = m.drop_duplicates('rated_at', keep=keep)
            out['u%s%d'%(keep,N)] = d.tail(N).liked.mean() if len(d) else np.nan
    # exponential moving alpha
    for a in [0.1,0.2,0.5]:
        out['ewm%g'%a] = m.liked.ewm(alpha=a).mean().iloc[-1] if len(m) else np.nan
    # time-window hours
    for H in [1,2,6,12,24]:
        w = m[m.rated_at >= t-pd.Timedelta(hours=H)]
        out['h%d'%H] = w.liked.mean() if len(w) else np.nan
    return out

hits={}
miss=[]
for _,row in j.head(60).iterrows():
    v = variants(row['member_id'], row['rated_at'])
    tgt = row['f_mbr_recent_rate']
    m2 = [k for k,val in v.items() if abs(val-tgt)<1e-9]
    if m2:
        for k in m2: hits[k]=hits.get(k,0)+1
    else:
        miss.append((row['rating_id'],tgt,sorted(v.items(), key=lambda kv:abs(kv[1]-tgt))[:3]))
print(hits)
for x in miss[:10]: print(x)
