    for col in ['liked','stars']:
        v=m[col].values
        for N in range(1,101):
            if len(v)>=N: res[(col,'raw',N)]=v[-N:].mean()
    # dedup by timestamp keep last
    d=m.drop_duplicates('rated_at',keep='last')
    v=d['liked'].values
    for N in range(1,61):
        if len(v)>=N: res[('liked','dedup_last',N)]=v[-N:].mean()
    d=m.drop_duplicates('rated_at',keep='first')
    v=d['liked'].values
    for N in range(1,61):
        if len(v)>=N: res[('liked','dedup_first',N)]=v[-N:].mean()
    # minute buckets mean
    mt=m.groupby(m.rated_at.dt.floor('min'))['liked'].mean()
    v=mt.values
    for N in range(1,31):
        if len(v)>=N: res[('liked','minute',N)]=v[-N:].mean()
    # ewm
    for a in [0.05,0.1,0.2,0.3,0.5,0.7]:
        if len(m): res[('liked','ewm',a)]=m.liked.ewm(alpha=a).mean().iloc[-1]
    ms=[k for k,val in res.items() if abs(val-tgt)<1e-9]
    if not ms: unmatched.append((row['rating_id'],mid,tgt))
    best.update(ms)
print(best.most_common(15))
print('unmatched',len(unmatched), unmatched[:8])
