import pandas as pd, numpy as np
r = pd.read_csv('data/ratings.csv.gz', dtype={'rating_id': str}, parse_dates=['rated_at'])
r = r.sort_values('rating_id').reset_index(drop=True)
s = pd.read_csv('reference/feature_sample.csv')
j = s.merge(r[['rating_id','member_id','rated_at']], on='rating_id')
mhist = {m:g.rated_at.values for m,g in r.groupby('member_id')}
t0 = np.datetime64('2000-11-22 00:00:00')

def gap_base(row, mode):
    ts = mhist[row['member_id']]
    m2 = ts[ts < np.datetime64(row['rated_at'])]
    if mode=='pos1':
        return m2[-2] if len(m2)>=2 else None
    elif mode=='pos1_or_t0':
        return m2[-2] if len(m2)>=2 else t0
    elif mode=='distinct':
        u = np.unique(m2)  # distinct times ascending
        return u[-2] if len(u)>=2 else (u[-1] if len(u) else t0)
    elif mode=='distinct_first':
        u = np.unique(m2)
        return u[-2] if len(u)>=2 else None
for mode in ['pos1','pos1_or_t0','distinct','distinct_first']:
    bad=[]
    for _,row in j.iterrows():
        b = gap_base(row, mode)
        if b is None:
            if not np.isnan(row['f_mbr_days_since_prev']): bad.append(row['rating_id'])
            continue
        d = (np.datetime64(row['rated_at'])-b)/np.timedelta64(1,'s')/86400.0
        if abs(round(d,6)-row['f_mbr_days_since_prev'])>1e-9: bad.append((row['rating_id'],row['f_mbr_days_since_prev'],round(d,6)))
    print(mode, 'bad', len(bad), bad[:6])
EOF"}

